/* MathWorksWinner.js
   Universal WinnerWindow module for MathWorks future lessons.
   Usage:
     MathWorksWinner.show({
       message: "You mastered this lesson!",
       continueText: "Continue",
       onContinue: () => { ... }
     });
*/
(function(global){
  "use strict";

  const DONATE_URL = "https://www.paypal.com/donate/?hosted_button_id=DMMXW39SYGURC";
  const WINNER_AUDIO = "data:audio/mpeg;base64,";
  let onContinueCallback = null;
  let built = false;
  let rewardPlaying = false;

  function build(){
    if(built) return;
    built = true;

    const style = document.createElement("style");
    style.id = "mathWorksWinnerStyle";
    style.textContent = `
      #mwWinnerOverlay{
        display:none; position:fixed; inset:0;
        background:rgba(15,23,42,.88); z-index:2147483000;
        color:white; align-items:center; justify-content:center;
        text-align:center; flex-direction:column; padding:20px;
        font-family:Arial,sans-serif;
      }
      #mwWinnerOverlay.show{display:flex}
      #mwWinnerCard{
        position:relative; width:min(92vw,620px);
        padding:30px 22px 26px; border-radius:26px;
        background:rgba(15,23,42,.72);
        box-shadow:0 22px 70px rgba(0,0,0,.45);
      }
      #mwWinnerBig{
        font-size:clamp(3rem,12vw,5rem);
        animation:mwWinnerPulse .9s infinite;
      }
      @keyframes mwWinnerPulse{50%{transform:scale(1.15)}}
      #mwWinnerTitle{
        margin:8px 0 10px; font-size:clamp(2rem,8vw,3.5rem);
      }
      #mwWinnerMessage{
        margin:0 0 12px; font-size:clamp(1.1rem,4vw,1.45rem);
        font-weight:800;
      }
      #mwWinnerClose{
        position:absolute; top:14px; right:14px;
        width:50px; height:50px; border-radius:50%; border:0;
        background:#e5edf4; color:#17324d; font-size:32px;
        line-height:1; font-weight:700; cursor:pointer;
      }
      #mwWinnerContinue{
        display:inline-block; margin-top:14px; padding:14px 24px;
        border-radius:18px; border:3px solid #0f4f7f;
        background:#1d6fb5; color:white; font-size:1.15rem;
        font-weight:900; cursor:pointer;
      }
      #mwWinnerDonate{
        display:inline-block; margin-top:18px; padding:16px 28px;
        border-radius:18px; background:#f59e0b; color:#172033;
        font-weight:900; font-size:1.2rem; text-decoration:none;
        border:4px solid #92400e; box-shadow:0 8px 20px rgba(0,0,0,.25);
      }
      .mwConfetti{
        position:fixed; top:-40px; z-index:2147483100;
        pointer-events:none; animation:mwFall linear forwards;
      }
      @keyframes mwFall{
        to{transform:translateY(115vh) rotate(720deg);opacity:0}
      }
      #mwFlashOverlay{
        position:fixed; inset:0; background:white; opacity:0;
        pointer-events:none; z-index:2147483050;
      }
      #mwFlashOverlay.mwFlashOn{
        animation:mwFlashAnim .22s linear 8;
      }
      @keyframes mwFlashAnim{
        0%{opacity:0} 50%{opacity:.8} 100%{opacity:0}
      }
    `;
    document.head.appendChild(style);

    const audio = document.createElement("audio");
    audio.id = "mwWinnerSong";
    audio.preload = "auto";
    audio.src = WINNER_AUDIO;
    document.body.appendChild(audio);

    const flash = document.createElement("div");
    flash.id = "mwFlashOverlay";
    document.body.appendChild(flash);

    const overlay = document.createElement("div");
    overlay.id = "mwWinnerOverlay";
    overlay.setAttribute("role","dialog");
    overlay.setAttribute("aria-modal","true");
    overlay.setAttribute("aria-labelledby","mwWinnerTitle");
    overlay.innerHTML = `
      <div id="mwWinnerCard">
        <button id="mwWinnerClose" aria-label="Close">×</button>
        <div id="mwWinnerBig">🎉🏆🎺</div>
        <h2 id="mwWinnerTitle">You are a Winner!</h2>
        <p id="mwWinnerMessage">You mastered this lesson!</p>
        <button id="mwWinnerContinue">Continue</button><br>
        <a id="mwWinnerDonate"
           href="${DONATE_URL}"
           target="_blank" rel="noopener">❤️ Support this work!</a>
      </div>
    `;
    document.body.appendChild(overlay);

    document.getElementById("mwWinnerClose").addEventListener("click", close);
    document.getElementById("mwWinnerContinue").addEventListener("click", function(){
      const cb = onContinueCallback;
      close();
      if(typeof cb === "function") {
        try{ cb(); }catch(e){ console.error(e); }
      }
    });
  }

  function setRewardControlsEnabled(enabled){
    const closeBtn = document.getElementById("mwWinnerClose");
    const continueBtn = document.getElementById("mwWinnerContinue");
    [closeBtn, continueBtn].forEach(btn=>{
      if(!btn) return;
      btn.disabled = !enabled;
      btn.setAttribute("aria-disabled", enabled ? "false" : "true");
      btn.style.opacity = enabled ? "1" : ".42";
      btn.style.cursor = enabled ? "pointer" : "default";
    });
  }

  function rewardFinished(){
    if(!rewardPlaying) return;
    rewardPlaying = false;
    setRewardControlsEnabled(true);
    try{ global.dispatchEvent(new CustomEvent("mwWinnerSongEnded")); }catch(e){}
  }

  function playSong(){
    const a = document.getElementById("mwWinnerSong");
    if(!a){ setRewardControlsEnabled(true); return; }
    try{
      a.pause();
      a.currentTime = 0;
      a.loop = false;
      rewardPlaying = true;
      setRewardControlsEnabled(false);
      a.onended = rewardFinished;
      a.onerror = rewardFinished;
      const p = a.play();
      if(p && p.catch) p.catch(()=>rewardFinished());
    }catch(e){ rewardFinished(); }
  }

  function flashScreen(){
    const f = document.getElementById("mwFlashOverlay");
    if(!f) return;
    f.classList.remove("mwFlashOn");
    void f.offsetWidth;
    f.classList.add("mwFlashOn");
  }

  function launchConfetti(){
    const pieces = ["🎉","🎊","✨","⭐","🎈","🥳"];
    for(let i=0;i<100;i++){
      const c = document.createElement("div");
      c.className = "mwConfetti";
      c.textContent = pieces[Math.floor(Math.random()*pieces.length)];
      c.style.left = (Math.random()*100) + "vw";
      c.style.fontSize = (24 + Math.random()*30) + "px";
      c.style.animationDuration = (3 + Math.random()*4) + "s";
      c.style.animationDelay = (Math.random()*0.8) + "s";
      document.body.appendChild(c);
      setTimeout(()=>c.remove(),8000);
    }
  }

  function show(options){
    build();
    options = options || {};
    rewardPlaying = false;
    setRewardControlsEnabled(true);

    const msg = document.getElementById("mwWinnerMessage");
    const btn = document.getElementById("mwWinnerContinue");
    const donate = document.getElementById("mwWinnerDonate");
    const overlay = document.getElementById("mwWinnerOverlay");

    msg.textContent = options.message || "You mastered this lesson!";
    btn.textContent = options.continueText || "Continue";
    const studentViewer = global.MathDoDaViewerMode === "student";
    donate.style.display = (options.showDonate === false || studentViewer) ? "none" : "inline-block";
    onContinueCallback = typeof options.onContinue === "function"
      ? options.onContinue : null;

    overlay.classList.add("show");
    flashScreen();
    launchConfetti();
    playSong();
  }

  function close(){
    const overlay = document.getElementById("mwWinnerOverlay");
    if(overlay) overlay.classList.remove("show");
    const a = document.getElementById("mwWinnerSong");
    if(a){ try{ a.pause(); }catch(e){} }
    rewardPlaying = false;
    setRewardControlsEnabled(true);
  }

  function init(){ build(); }

  global.MathWorksWinner = {
    init,
    show,
    close
  };
})(window);
